import{bV as t,aL as d,u as r,G as o}from"./chunks/framework.DT-LCgF3.js";const b=JSON.parse('{"title":"RAG 完整链路与架构选型（7）模型选型","description":"","frontmatter":{"date":"2026-11-25T14:00:00.000Z","title":"RAG 完整链路与架构选型（7）模型选型","permalink":"/pages/rag07","categories":["AI","RAG"]},"headers":[],"relativePath":"AI/02.RAG/完整链路与架构选型/07.模型选型.md","filePath":"AI/02.RAG/完整链路与架构选型/07.模型选型.md","lastUpdated":1795655557000}'),a={name:"AI/02.RAG/完整链路与架构选型/07.模型选型.md"};function n(c,e,g,i,h,s){return d(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="rag-完整链路与架构选型-7-模型选型" tabindex="-1">RAG 完整链路与架构选型（7）模型选型 <a class="header-anchor" href="#rag-完整链路与架构选型-7-模型选型" aria-label="Permalink to &quot;RAG 完整链路与架构选型（7）模型选型&quot;">​</a></h1><h2 id="七、模型选型——国内方案对比" tabindex="-1">七、模型选型——国内方案对比 <a class="header-anchor" href="#七、模型选型——国内方案对比" aria-label="Permalink to &quot;七、模型选型——国内方案对比&quot;">​</a></h2><p>本章范围严格限定在国内：国产开源、可私有化部署的模型，以及国内云厂商提供的 API 服务。国外的 OpenAI、Cohere、Voyage、Jina 等不在本章讨论范围内，也不作为对比基线引入。</p><p>本章所有参数量、向量维度、输入长度、许可与价格，均保留素材给出的原始来源，来源编号见表下注释。抓取与查看日期统一为 <strong>2026-11-24</strong>。凡素材未能从官方来源取得的值，一律在单元格中标注「未核实」，不填推测值。价格类信息为官方展示价，以控制台结算为准。</p><p>来源的类型分三档，证据强度不同：仓库中的 <code>config.json</code>、<code>sentence_bert_config.json</code>、<code>1_Pooling/config.json</code> 属于一手证据；模型卡正文的参数表格属于官方声明；云厂商文档中的表格属于官方声明。本章在正文中明确区分这三档，引用规格时不要混用。</p><p>读这四张表时需要先理解三个口径，否则很容易把不同来源的数字当同一回事比较。第一是维度与精度的关系：表中的维度是模型的输出维度，也是向量库的建索引维度。维度直接决定存储与内存占用，一个 100 万条、4096 维、单精度浮点的向量集合，仅向量本身就在十 GB 量级，维度减半存储基本减半。因此「可自定义维度」在本章中不是宣传语，而是实实在在的成本开关，凡涉及它的模型，正文都会额外说明截断会带来的精度代价。第二是最大输入长度与分块策略的关系：输入长度是模型的硬上限，不是推荐值。工程上按上限长度的三分之一到二分之一切块，再叠加适量的重叠，通常比贴着上限切更稳。表中凡出现「模型卡」与「config」两个值的情况，说明模型卡声明与仓库配置文件不一致，此时应以更保守的那个值为设计依据。第三是参数量与显存的关系：参数量是权重张量的元素总数，不是运行时的显存占用。按半精度估算，权重约占参数量两倍的字节数，此外还要加上激活值、批处理带来的 KV 缓存，以及检索场景中批量编码时的中间张量。本章表格提供的是估算起点，不是部署结论。</p><p>还有一点应提前说明：本章表格记录的是 2026-11-24 这一时点的状态。模型规格、许可条款、云服务的在架与下线状态都会变动，把本章数值写进设计方案之前应重新核对来源链接。特别是许可与下线两类信息，一旦变化就会直接推翻选型结论。</p><h3 id="_7-1-embedding-模型" tabindex="-1">7.1 Embedding 模型 <a class="header-anchor" href="#_7-1-embedding-模型" aria-label="Permalink to &quot;7.1 Embedding 模型&quot;">​</a></h3><h4 id="_7-1-1-开源可私有化部署" tabindex="-1">7.1.1 开源可私有化部署 <a class="header-anchor" href="#_7-1-1-开源可私有化部署" aria-label="Permalink to &quot;7.1.1 开源可私有化部署&quot;">​</a></h4><p>开源侧的取值口径需要先说明：向量维度取 <code>1_Pooling/config.json</code> 的 <code>word_embedding_dimension</code>，与 <code>config.json</code> 的 <code>hidden_size</code> 一致；最大输入长度优先取 <code>sentence_bert_config.json</code> 的 <code>max_seq_length</code>，该文件缺失时退回 <code>config.json</code> 的 <code>max_position_embeddings</code>；参数量取 HuggingFace API 的 <code>safetensors.total</code>，即张量元素总数。</p><p><strong>核心参数表</strong></p><table tabindex="0"><thead><tr><th>模型</th><th>发布方</th><th>参数量</th><th>维度</th><th>最大输入</th><th>多语言</th><th>许可</th><th>源</th></tr></thead><tbody><tr><td>bge-large-zh-v1.5</td><td>智源</td><td>未核实¹</td><td>1024</td><td>512</td><td>中文为主</td><td>MIT</td><td>1</td></tr><tr><td>bge-base-zh-v1.5</td><td>智源</td><td>未核实¹</td><td>768</td><td>512</td><td>中文为主</td><td>MIT</td><td>2</td></tr><tr><td>bge-small-zh-v1.5</td><td>智源</td><td>23,954,432</td><td>512</td><td>512</td><td>中文为主</td><td>MIT</td><td>3</td></tr><tr><td>bge-m3</td><td>智源</td><td>未核实¹（同族 <code>bge-m3-unsupervised</code> 为 567,754,752）</td><td>1024</td><td>8192</td><td>多语言</td><td>MIT</td><td>4</td></tr><tr><td>bge-multilingual-gemma2</td><td>智源</td><td>9,241,713,152</td><td>3584</td><td>8192</td><td>多语言</td><td>Gemma 许可（非标准开源）</td><td>5</td></tr><tr><td>bge-reasoner-embed-qwen3-8b-0923</td><td>智源</td><td>7,568,405,504</td><td>4096</td><td>32K（模型卡）；config 40,960</td><td>未核实</td><td>apache-2.0</td><td>6</td></tr><tr><td>gte-Qwen2-7B-instruct</td><td>阿里</td><td>7,612,620,288</td><td>3584</td><td>32,768（config 131,072）</td><td>多语言</td><td>apache-2.0</td><td>7</td></tr><tr><td>gte-multilingual-base</td><td>阿里</td><td>305,369,089</td><td>768（可 128–768 截断）</td><td>8192</td><td>多语言（语言标签 70+）</td><td>apache-2.0</td><td>8</td></tr><tr><td>gte-large-en-v1.5</td><td>阿里</td><td>434,139,136</td><td>1024</td><td>8192</td><td>英文</td><td>apache-2.0</td><td>9</td></tr><tr><td>gte-modernbert-base</td><td>阿里</td><td>149,014,272</td><td>768</td><td>8192</td><td>英文</td><td>apache-2.0</td><td>10</td></tr><tr><td>Qwen3-Embedding-0.6B</td><td>阿里</td><td>595,776,512</td><td>1024（可自定义 32–1024）</td><td>32K（config 32,768）</td><td>多语言</td><td>apache-2.0</td><td>11</td></tr><tr><td>Qwen3-Embedding-4B</td><td>阿里</td><td>4,021,774,336</td><td>2560（可自定义 32–2560）</td><td>32K（config 40,960）</td><td>多语言</td><td>apache-2.0</td><td>12</td></tr><tr><td>Qwen3-Embedding-8B</td><td>阿里</td><td>7,567,295,488</td><td>4096（可自定义 32–4096）</td><td>32K（config 40,960）</td><td>多语言</td><td>apache-2.0</td><td>13</td></tr><tr><td>Qwen3-VL-Embedding-8B</td><td>阿里</td><td>8,144,793,840</td><td>4096（可自定义 64–4096）</td><td>32K（模型卡）；text config 262,144</td><td>30+ 语言</td><td>apache-2.0</td><td>14</td></tr><tr><td>E2Rank-8B</td><td>阿里</td><td>7,568,405,504</td><td>4096</td><td>40,960</td><td>未核实</td><td>apache-2.0</td><td>15</td></tr><tr><td>GVE-7B</td><td>阿里</td><td>8,292,166,656</td><td>未核实</td><td>128,000（config）</td><td>英文标签</td><td>apache-2.0</td><td>16</td></tr><tr><td>LaSER-Qwen3-8B</td><td>阿里</td><td>8,190,735,360</td><td>4096</td><td>8192（模型卡）</td><td>英文标签</td><td>MIT</td><td>17</td></tr><tr><td>core-emb-8b</td><td>阿里</td><td>未核实¹</td><td>4096</td><td>262,144（config）</td><td>多模态</td><td>CC-BY-4.0</td><td>18</td></tr><tr><td>core-emb-2b</td><td>阿里</td><td>未核实¹</td><td>2048</td><td>262,144（config）</td><td>多模态</td><td>CC-BY-4.0</td><td>19</td></tr><tr><td>UEmbed-9B</td><td>阿里</td><td>8,392,695,024</td><td>未核实</td><td>未核实</td><td>多模态</td><td>CC-BY-4.0</td><td>20</td></tr><tr><td>Conan-embedding-v1</td><td>腾讯（TencentBAC）</td><td>325,522,432</td><td>1024</td><td>512</td><td>中文</td><td>CC-BY-NC-4.0（禁止商用）</td><td>21</td></tr><tr><td>Conan-embedding-v2</td><td>腾讯（TencentBAC）</td><td>1.48B（模型卡：非 dense 层参数）</td><td>3584</td><td>32,768</td><td>中英</td><td>apache-2.0</td><td>22</td></tr><tr><td>m3e-base</td><td>MokaAI</td><td>未核实²</td><td>768</td><td>512</td><td>中文</td><td>未核实²</td><td>23</td></tr><tr><td>m3e-large</td><td>MokaAI</td><td>未核实¹</td><td>1024</td><td>512</td><td>中英</td><td>未核实（HF 未标注许可）</td><td>24</td></tr><tr><td>text2vec-base-chinese</td><td>社区（shibing624）</td><td>102,268,160</td><td>768</td><td>128（config 512）</td><td>中文</td><td>apache-2.0</td><td>25</td></tr><tr><td>text2vec-large-chinese</td><td>社区（shibing624）</td><td>未核实³</td><td>未核实³</td><td>未核实³</td><td>中文</td><td>未核实³</td><td>26</td></tr></tbody></table><p><strong>来源表</strong>（第 7.1.1 节与第 7.2.1 节共用；均为 HuggingFace 模型卡链接）</p><ol><li><a href="https://huggingface.co/BAAI/bge-large-zh-v1.5" target="_blank" rel="noreferrer">BAAI/bge-large-zh-v1.5</a></li><li><a href="https://huggingface.co/BAAI/bge-base-zh-v1.5" target="_blank" rel="noreferrer">BAAI/bge-base-zh-v1.5</a></li><li><a href="https://huggingface.co/BAAI/bge-small-zh-v1.5" target="_blank" rel="noreferrer">BAAI/bge-small-zh-v1.5</a></li><li><a href="https://huggingface.co/BAAI/bge-m3" target="_blank" rel="noreferrer">BAAI/bge-m3</a></li><li><a href="https://huggingface.co/BAAI/bge-multilingual-gemma2" target="_blank" rel="noreferrer">BAAI/bge-multilingual-gemma2</a></li><li><a href="https://huggingface.co/BAAI/bge-reasoner-embed-qwen3-8b-0923" target="_blank" rel="noreferrer">BAAI/bge-reasoner-embed-qwen3-8b-0923</a></li><li><a href="https://huggingface.co/Alibaba-NLP/gte-Qwen2-7B-instruct" target="_blank" rel="noreferrer">Alibaba-NLP/gte-Qwen2-7B-instruct</a></li><li><a href="https://huggingface.co/Alibaba-NLP/gte-multilingual-base" target="_blank" rel="noreferrer">Alibaba-NLP/gte-multilingual-base</a></li><li><a href="https://huggingface.co/Alibaba-NLP/gte-large-en-v1.5" target="_blank" rel="noreferrer">Alibaba-NLP/gte-large-en-v1.5</a></li><li><a href="https://huggingface.co/Alibaba-NLP/gte-modernbert-base" target="_blank" rel="noreferrer">Alibaba-NLP/gte-modernbert-base</a></li><li><a href="https://huggingface.co/Qwen/Qwen3-Embedding-0.6B" target="_blank" rel="noreferrer">Qwen/Qwen3-Embedding-0.6B</a></li><li><a href="https://huggingface.co/Qwen/Qwen3-Embedding-4B" target="_blank" rel="noreferrer">Qwen/Qwen3-Embedding-4B</a></li><li><a href="https://huggingface.co/Qwen/Qwen3-Embedding-8B" target="_blank" rel="noreferrer">Qwen/Qwen3-Embedding-8B</a></li><li><a href="https://huggingface.co/Qwen/Qwen3-VL-Embedding-8B" target="_blank" rel="noreferrer">Qwen/Qwen3-VL-Embedding-8B</a></li><li><a href="https://huggingface.co/Alibaba-NLP/E2Rank-8B" target="_blank" rel="noreferrer">Alibaba-NLP/E2Rank-8B</a></li><li><a href="https://huggingface.co/Alibaba-NLP/GVE-7B" target="_blank" rel="noreferrer">Alibaba-NLP/GVE-7B</a></li><li><a href="https://huggingface.co/Alibaba-NLP/LaSER-Qwen3-8B" target="_blank" rel="noreferrer">Alibaba-NLP/LaSER-Qwen3-8B</a></li><li><a href="https://huggingface.co/Alibaba-NLP/core-emb-8b" target="_blank" rel="noreferrer">Alibaba-NLP/core-emb-8b</a></li><li><a href="https://huggingface.co/Alibaba-NLP/core-emb-2b" target="_blank" rel="noreferrer">Alibaba-NLP/core-emb-2b</a></li><li><a href="https://huggingface.co/Alibaba-NLP/UEmbed-9B" target="_blank" rel="noreferrer">Alibaba-NLP/UEmbed-9B</a></li><li><a href="https://huggingface.co/TencentBAC/Conan-embedding-v1" target="_blank" rel="noreferrer">TencentBAC/Conan-embedding-v1</a></li><li><a href="https://huggingface.co/TencentBAC/Conan-embedding-v2" target="_blank" rel="noreferrer">TencentBAC/Conan-embedding-v2</a></li><li><a href="https://huggingface.co/moka-ai/m3e-base" target="_blank" rel="noreferrer">moka-ai/m3e-base</a></li><li><a href="https://huggingface.co/moka-ai/m3e-large" target="_blank" rel="noreferrer">moka-ai/m3e-large</a></li><li><a href="https://huggingface.co/shibing624/text2vec-base-chinese" target="_blank" rel="noreferrer">shibing624/text2vec-base-chinese</a></li><li><a href="https://huggingface.co/shibing624/text2vec-large-chinese" target="_blank" rel="noreferrer">shibing624/text2vec-large-chinese</a></li></ol><p>注释：</p><ol><li>该仓库未提供 <code>safetensors</code> 索引，参数量无法从 HuggingFace API 直接取得，标注<strong>未核实</strong>。</li><li><code>moka-ai/m3e-base</code> 的 HuggingFace API 元数据在本次抓取中失败（连接中断），仅成功取得 <code>config.json</code> 与 <code>1_Pooling/config.json</code>；参数量与许可均<strong>未核实</strong>。</li><li><code>shibing624/text2vec-large-chinese</code> 的仓库 API 返回 HTTP 401（可能已转为受限访问），全部字段<strong>未核实</strong>。</li></ol><p><strong>一手证据与归属订正</strong></p><p><code>bge-m3</code> 的 <code>config.json</code> 实测值：<code>model_type=xlm-roberta</code>、<code>hidden_size=1024</code>、<code>num_hidden_layers=24</code>、<code>max_position_embeddings=8194</code>、<code>vocab_size=250002</code>；<code>sentence_bert_config.json</code> 为 <code>{&quot;max_seq_length&quot;: 8192}</code>。这与外部惯例引用的「1024 维、8192 长度、MIT」一致，可用作该模型规格的核对基准。该模型对应论文为 arXiv:2402.03216；同族重排模型 <code>bge-reranker-v2-m3</code> 的官方模型卡亦引用该编号与 arXiv:2312.15503。</p><p><code>Qwen3-Embedding-8B</code> 的 <code>config.json</code> 实测值：<code>model_type=qwen3</code>、<code>hidden_size=4096</code>、<code>num_hidden_layers=36</code>、<code>max_position_embeddings=40960</code>；模型卡标注 <code>Context Length: 32k</code>、<code>Number of Parameters: 8B</code>，基座为 <code>Qwen/Qwen3-8B-Base</code>，并附论文链接 <code>arXiv:2506.05176</code>。<strong>这里存在一处需要在工程中留意的差异</strong>：模型卡写 32K，而 config 写 40,960。同一现象在 <code>Qwen3-Embedding-4B</code>（config 40,960）与 <code>Qwen3-Embedding-0.6B</code>（config 32,768）上同样存在。按 32K 设计分块策略是更保守的做法；若要把实际输入推到 config 上限，须自行验证位置编码外推后的检索质量。</p><p><code>Conan-embedding-v2</code> 的模型卡标注：Hidden Layer Dimension 3584、FFN 中间维 8192、上下文 32,768 tokens、非 dense 层参数量 1.48B。该仓库<strong>无 <code>config.json</code></strong>（HTTP 404），因此上述数值只能按官方声明采用，无法用一手文件交叉验证。参数量单元格中的 1.48B 是模型卡口径，与常规的「总参数量」不可直接横向比较。</p><p>关于 Conan-embedding 的归属需要订正：其 HuggingFace 组织为 <code>TencentBAC</code>，本章据此记为腾讯，业界常被误记为网易。该组织的完整机构名称<strong>未核实</strong>；如需在对外材料中署名，请以 <a href="https://huggingface.co/TencentBAC" target="_blank" rel="noreferrer">TencentBAC 组织页</a> 与论文原文为准。</p><p>另外注意，「未核实」在各模型上的成因不同：<code>bge-large-zh-v1.5</code>、<code>bge-base-zh-v1.5</code>、<code>bge-m3</code> 以及 <code>core-emb-8b</code>、<code>core-emb-2b</code>、<code>m3e-large</code> 是仓库未提供 <code>safetensors</code> 索引；<code>m3e-base</code> 与 <code>Yi-1.5-34B-Chat</code> 是抓取连接中断；<code>text2vec-large-chinese</code> 是仓库返回 HTTP 401。成因不同意味着可补救程度不同，前两类通常可换一个抓取时点补齐。</p><p>从这张表可以看出开源 Embedding 已经形成了明显的几档。第一档是以 512 长度档为主的中文小模型，包括 <code>bge-small-zh-v1.5</code>、<code>bge-base-zh-v1.5</code>、<code>bge-large-zh-v1.5</code>、<code>m3e-base</code>、<code>m3e-large</code>、<code>Conan-embedding-v1</code> 与 <code>text2vec</code> 系列（本档为档位概览，个别模型的实际取值见上表；其中 <code>text2vec</code> 系列部分字段未核实）。这一档的定位是把检索跑起来，显存与推理成本都低，缺点是 512 长度对企业内部文档中的长条款、长产品说明不够用，必须切得比较碎，容易切断语义。第二档是 8192 至 32768 长度的中量级模型，包括 <code>bge-m3</code>、<code>gte-multilingual-base</code>、<code>gte-large-en-v1.5</code>、<code>gte-modernbert-base</code>、<code>Conan-embedding-v2</code> 与 <code>Qwen3-Embedding-0.6B</code>。这一档是当前私有化部署的主力，长度基本够用，参数量从一亿多到十四亿多，单张消费级显卡即可承载（该档偏大成员如 <code>Conan-embedding-v2</code> 建议按实际显存实测）。第三档是 4B 至 9B 的大模型，包括 <code>Qwen3-Embedding-4B</code>、<code>Qwen3-Embedding-8B</code>、<code>Qwen3-VL-Embedding-8B</code>、<code>bge-multilingual-gemma2</code> 与若干阿里系的推理检索模型。这一档的检索质量预期更高，但推理成本和部署门槛都上了一个台阶，通常只在检索质量是明确瓶颈时才采用。</p><p>另一个值得单独指出的分组是「推理式检索」。<code>bge-reasoner-embed-qwen3-8b-0923</code>、<code>E2Rank-8B</code>、<code>GVE-7B</code>、<code>LaSER-Qwen3-8B</code> 以及 core 与 UEmbed 系列都归入这一类。它们的共同特征是参数量集中在 7B 至 8B 附近，其中 <code>bge-reasoner-embed-qwen3-8b-0923</code> 与 <code>E2Rank-8B</code> 的参数量一致（均为 7,568,405,504），且都与 Qwen3-8B 基座相关。这类模型在检索前或检索中引入额外的推理或组合步骤，效果上限可能更高，但带来的延迟与成本也更高，且其中多款的多语言能力标注为「未核实」或仅标英文。对企业文档问答这类以中文为主、延迟敏感的场景，把它们作为第一选择需要额外的评测理由。</p><p>同一发布方内部的命名规律也值得留意。智源的 <code>bge-*</code> 系列中，<code>-v1.5</code> 后缀是 512 长度的中文优化版本，<code>-m3</code> 是多语言长文本版本，<code>-gemma2</code> 后缀则表示以 Gemma2 为基座。判断许可时不能只看前缀，<code>bge-m3</code> 是 MIT 而 <code>bge-multilingual-gemma2</code> 是 Gemma 许可，两者同属智源但合规路径完全不同。阿里侧的 <code>gte-*</code> 与 <code>Qwen3-*</code> 两套命名对应两条技术线，前者多为 8192 长度、参数量较小，后者多为 32K 长度、参数量较大，但两者在许可上都是 apache-2.0，选择时主要看长度需求与显存预算，不必顾虑许可差异。</p><h4 id="_7-1-2-云厂商-api" tabindex="-1">7.1.2 云厂商 API <a class="header-anchor" href="#_7-1-2-云厂商-api" aria-label="Permalink to &quot;7.1.2 云厂商 API&quot;">​</a></h4><p>数据来自厂商官方文档页，查看日期 2026-11-24。</p><table tabindex="0"><thead><tr><th>服务商</th><th>模型</th><th>维度</th><th>单条最大输入</th><th>语言 / 模态</th><th>价格</th><th>源</th></tr></thead><tbody><tr><td>阿里云百炼</td><td>qwen3.7-text-embedding</td><td>2560 / 2048 / 1536 / 1024（默认）/ 768 / 512 / 256</td><td>128,000 token</td><td>201 种主流语种与方言；纯文本</td><td>0.0005 元/千输入 token</td><td>27</td></tr><tr><td>阿里云百炼</td><td>qwen3.7-text-embedding-flash</td><td>1024（默认）/ 768 / 512 / 256</td><td>128,000 token</td><td>201 种主流语种与方言；纯文本</td><td>0.000125 元/千输入 token</td><td>27</td></tr><tr><td>阿里云百炼</td><td>text-embedding-v4</td><td>2048 / 1536 / 1024（默认）/ 768 / 512 / 256 / 128 / 64</td><td>8,192 token</td><td>100+ 主流语种及多种编程语言；纯文本</td><td>0.0005 元/千输入 token</td><td>27</td></tr><tr><td>阿里云百炼</td><td>text-embedding-v3</td><td>1024（默认）/ 768 / 512 / 256 / 128 / 64</td><td>8,192 token</td><td>50+ 主流语种；纯文本</td><td>未核实</td><td>27</td></tr><tr><td>阿里云百炼</td><td>text-embedding-v2</td><td>1536</td><td>2,048 token</td><td>多语种；纯文本</td><td>0.0007 元/千输入 token</td><td>27</td></tr><tr><td>阿里云百炼</td><td>text-embedding-v1</td><td>未核实</td><td>2,048 token</td><td>多语种；纯文本</td><td>未核实</td><td>27</td></tr><tr><td>智谱 BigModel</td><td>embedding-3</td><td>256–2048 可自定义（默认 2048，常用 1024 / 512）</td><td>单条最多 3,072 token，数组最多 64 条</td><td>未核实；纯文本</td><td>0.5 元/百万 token</td><td>28</td></tr><tr><td>火山引擎方舟</td><td>doubao-embedding-vision-251215</td><td>默认 2048，可用 <code>dimensions</code> 指定</td><td>未核实</td><td>未核实；文本 / 图片 / 视频</td><td>未核实</td><td>29</td></tr><tr><td>火山引擎方舟</td><td>doubao-embedding-vision-250615</td><td>同上</td><td>未核实</td><td>未核实；文本 / 图片 / 视频</td><td>未核实</td><td>29（已停止新购，存量可用）</td></tr><tr><td>百度千帆</td><td>Embedding-V1</td><td>未核实</td><td>token ≤ 384 且 ≤ 1000 字符</td><td>中文；纯文本</td><td>未核实</td><td>30</td></tr><tr><td>百度千帆</td><td>bge-large-zh / bge-large-en</td><td>未核实</td><td>token ≤ 512 且 ≤ 2000 字符</td><td>中文 / 英文；纯文本</td><td>未核实</td><td>30</td></tr><tr><td>百度千帆</td><td>Qwen3-Embedding-0.6B / 4B</td><td>未核实（托管第三方模型）</td><td>每文本最多 8K token</td><td>多语言；纯文本</td><td>未核实</td><td>30</td></tr></tbody></table><p>来源：27. <a href="https://help.aliyun.com/zh/model-studio/text-embedding-synchronous-api" target="_blank" rel="noreferrer">阿里云百炼文本向量同步 API</a>；28. <a href="https://docs.bigmodel.cn/cn/guide/models/embedding/embedding-3" target="_blank" rel="noreferrer">智谱 embedding-3</a>；29. <a href="https://ark.volcengine.com/region:cn-beijing/docs/vectorization" target="_blank" rel="noreferrer">火山引擎方舟向量化文档</a>；30. <a href="https://cloud.baidu.com/doc/qianfan-api/s/Fm7u3ropn" target="_blank" rel="noreferrer">百度千帆 Embeddings API</a>。</p><p><strong>阿里云百炼补充事实（一手文档）</strong></p><p><code>dimensions</code> 为可选参数，取值受限：2560 仅适用于 <code>qwen3.7-text-embedding</code>；2048 与 1536 仅适用于 <code>text-embedding-v4</code>；其余 1024 / 768 / 512 / 256 / 128 / 64 通用，默认 1024。输入为字符串时最长 128,000 token（v3.7 系列）；为字符串列表时最多 20 条，每条最长 128,000 token。<code>output_type</code> 支持 <code>dense</code> / <code>sparse</code> / <code>dense&amp;sparse</code>，稀疏向量输出仅适用于 <code>qwen3.7-text-embedding</code>、<code>text-embedding-v3</code>、<code>text-embedding-v4</code>，且仅支持 DashScope 接口调用。<code>text_type</code> 用于区分 <code>query</code> / <code>document</code>；<code>instruct</code> 参数仅在 <code>text_type=query</code> 时生效，官方称通常带来约 1%–5% 的效果提升。</p><p><strong>火山引擎方舟补充事实（一手文档）</strong></p><p>在架向量模型为 <code>doubao-embedding-vision</code> 系列，官方定位是多模态向量化模型，可将文本、图片、视频的混合输入转换为统一向量表示。版本差异：<code>250615</code> 起支持稀疏向量（Sparse Embedding，仅文本输入）与视频输入；<code>251215</code> 起支持多向量（Multi Embedding）、自定义视频抽帧与 <code>instructions</code> 字段；<code>250615</code> <strong>已停止新购，存量可用</strong>。<code>dimensions</code> 可指定稠密向量输出维度（文档示例取 1024），文档同时给出模型默认输出维度为 2048；稀疏向量为固定维度，不支持单独设置。视频 token 用量方面，单视频约在 10K–80K token 区间；<code>max_video_tokens</code> 取值范围 [10240, 204800]，<code>min_frame_tokens</code> / <code>max_frame_tokens</code> 用于控制单帧 token 上下限。官方特别提示：不同模型版本或 <code>instructions</code> 配置会改变向量空间与相似度分数，<strong>不应直接比较不同配置下的绝对分数</strong>，检索效果应以同配置下的相对排序为准。单价<strong>未核实</strong>，未在本次抓取到的页面中出现。</p><p><strong>百度千帆补充事实（一手文档）</strong></p><p>API 端点为 <code>https://qianfan.baidubce.com/v2/embeddings</code>。每个文本的输入限制按模型区分，见上表。批量限制：<code>tao-8k</code> 的文本数量只能为 1，其他模型不超过 16 条。多模态向量模型在该文档中标注「适用模型：暂无」，且只支持单个元素输入，不支持批量。维度与单价均<strong>未核实</strong>。</p><h3 id="_7-2-reranker-模型" tabindex="-1">7.2 Reranker 模型 <a class="header-anchor" href="#_7-2-reranker-模型" aria-label="Permalink to &quot;7.2 Reranker 模型&quot;">​</a></h3><h4 id="_7-2-1-开源可私有化部署" tabindex="-1">7.2.1 开源可私有化部署 <a class="header-anchor" href="#_7-2-1-开源可私有化部署" aria-label="Permalink to &quot;7.2.1 开源可私有化部署&quot;">​</a></h4><table tabindex="0"><thead><tr><th>模型</th><th>发布方</th><th>基座</th><th>参数量</th><th>最大输入</th><th>语言</th><th>许可</th><th>源</th></tr></thead><tbody><tr><td>bge-reranker-v2-m3</td><td>智源</td><td>bge-m3</td><td>567,755,777</td><td>8194（config）</td><td>多语言</td><td>apache-2.0</td><td>31</td></tr><tr><td>bge-reranker-v2-gemma</td><td>智源</td><td>Gemma</td><td>2,506,172,416</td><td>8192</td><td>多语言</td><td>apache-2.0</td><td>32</td></tr><tr><td>bge-reranker-v2-minicpm-layerwise</td><td>智源</td><td>MiniCPM</td><td>2,724,956,928</td><td>2048</td><td>多语言</td><td>apache-2.0</td><td>33</td></tr><tr><td>bge-reranker-v2.5-gemma2-lightweight</td><td>智源</td><td>Gemma2（cost-wise）</td><td>9,241,831,424</td><td>8192</td><td>多语言</td><td>Gemma 许可</td><td>34</td></tr><tr><td>bge-reranker-large</td><td>智源</td><td>XLM-RoBERTa</td><td>559,891,971</td><td>514</td><td>中英</td><td>MIT</td><td>35</td></tr><tr><td>bge-reranker-base</td><td>智源</td><td>XLM-RoBERTa</td><td>278,044,931</td><td>514</td><td>中英</td><td>MIT</td><td>36</td></tr><tr><td>Qwen3-Reranker-0.6B</td><td>阿里</td><td>Qwen3-0.6B-Base</td><td>595,776,512</td><td>40,960（config）</td><td>多语言</td><td>apache-2.0</td><td>37</td></tr><tr><td>Qwen3-Reranker-4B</td><td>阿里</td><td>Qwen3-4B-Base</td><td>4,021,784,576</td><td>40,960（config）</td><td>多语言</td><td>apache-2.0</td><td>38</td></tr><tr><td>Qwen3-Reranker-8B</td><td>阿里</td><td>Qwen3-8B-Base</td><td>8,188,548,096</td><td>40,960（config）</td><td>多语言</td><td>apache-2.0</td><td>39</td></tr><tr><td>Qwen3-VL-Reranker-8B</td><td>阿里</td><td>Qwen3-VL-8B-Instruct</td><td>8,767,123,696</td><td>32K（模型卡）；text config 262,144</td><td>30+ 语言</td><td>apache-2.0</td><td>40</td></tr><tr><td>gte-reranker-modernbert-base</td><td>阿里</td><td>ModernBERT-base</td><td>149,605,633</td><td>8192</td><td>英文</td><td>apache-2.0</td><td>41</td></tr><tr><td>gte-multilingual-reranker-base</td><td>阿里</td><td>gte-multilingual</td><td>305,959,681</td><td>8192</td><td>多语言</td><td>apache-2.0</td><td>42</td></tr><tr><td>core-reranker-8b</td><td>阿里</td><td>Qwen3-VL</td><td>8,767,123,696</td><td>262,144（config）</td><td>多模态</td><td>CC-BY-4.0</td><td>43</td></tr><tr><td>core-reranker-2b</td><td>阿里</td><td>Qwen3-VL</td><td>2,127,532,032</td><td>262,144（config）</td><td>多模态</td><td>CC-BY-4.0</td><td>44</td></tr><tr><td>E2Rank-8B</td><td>阿里</td><td>Qwen3-8B</td><td>7,568,405,504</td><td>40,960</td><td>未核实</td><td>apache-2.0</td><td>15</td></tr></tbody></table><p>来源：31. <a href="https://huggingface.co/BAAI/bge-reranker-v2-m3" target="_blank" rel="noreferrer">BAAI/bge-reranker-v2-m3</a>；32. <a href="https://huggingface.co/BAAI/bge-reranker-v2-gemma" target="_blank" rel="noreferrer">BAAI/bge-reranker-v2-gemma</a>；33. <a href="https://huggingface.co/BAAI/bge-reranker-v2-minicpm-layerwise" target="_blank" rel="noreferrer">BAAI/bge-reranker-v2-minicpm-layerwise</a>；34. <a href="https://huggingface.co/BAAI/bge-reranker-v2.5-gemma2-lightweight" target="_blank" rel="noreferrer">BAAI/bge-reranker-v2.5-gemma2-lightweight</a>；35. <a href="https://huggingface.co/BAAI/bge-reranker-large" target="_blank" rel="noreferrer">BAAI/bge-reranker-large</a>；36. <a href="https://huggingface.co/BAAI/bge-reranker-base" target="_blank" rel="noreferrer">BAAI/bge-reranker-base</a>；37. <a href="https://huggingface.co/Qwen/Qwen3-Reranker-0.6B" target="_blank" rel="noreferrer">Qwen/Qwen3-Reranker-0.6B</a>；38. <a href="https://huggingface.co/Qwen/Qwen3-Reranker-4B" target="_blank" rel="noreferrer">Qwen/Qwen3-Reranker-4B</a>；39. <a href="https://huggingface.co/Qwen/Qwen3-Reranker-8B" target="_blank" rel="noreferrer">Qwen/Qwen3-Reranker-8B</a>；40. <a href="https://huggingface.co/Qwen/Qwen3-VL-Reranker-8B" target="_blank" rel="noreferrer">Qwen/Qwen3-VL-Reranker-8B</a>；41. <a href="https://huggingface.co/Alibaba-NLP/gte-reranker-modernbert-base" target="_blank" rel="noreferrer">Alibaba-NLP/gte-reranker-modernbert-base</a>；42. <a href="https://huggingface.co/Alibaba-NLP/gte-multilingual-reranker-base" target="_blank" rel="noreferrer">Alibaba-NLP/gte-multilingual-reranker-base</a>；43. <a href="https://huggingface.co/Alibaba-NLP/core-reranker-8b" target="_blank" rel="noreferrer">Alibaba-NLP/core-reranker-8b</a>；44. <a href="https://huggingface.co/Alibaba-NLP/core-reranker-2b" target="_blank" rel="noreferrer">Alibaba-NLP/core-reranker-2b</a>。</p><p>实现差异需要注意：<code>Qwen3-Reranker-*</code> 是交叉编码器（<code>CrossEncoder</code>）实现，通过 causal logits 打分，<code>config_sentence_transformers.json</code> 中 <code>model_type=CrossEncoder</code>。这意味着它不能按双编码器方式预先建立文档向量索引，每次打分都要把 query 与候选文档成对送入模型，推理成本随候选数线性增长，工程上必须先做粗召回再重排。<code>E2Rank</code> 系列在 HuggingFace 上同时带 <code>feature-extraction</code> 与 <code>reranking</code> 标签，属于「检索 + 重排」统一模型，接入方式与单纯的交叉编码器不同。</p><p>选重排模型时，参数量是最容易被误用的一个指标。上表中 <code>bge-reranker-v2-m3</code> 为 567,755,777，<code>bge-reranker-large</code> 为 559,891,971，两者参数量几乎相同，但前者支持 8194 长度与多语言，后者仅支持 514 长度与中英，代际差异体现在基座与训练数据而不是参数规模。同理，<code>bge-reranker-v2-gemma</code>（2,506,172,416）与 <code>bge-reranker-v2-minicpm-layerwise</code>（2,724,956,928）参数量相近，但最大输入分别是 8192 与 2048，后者适用的是候选块较短的场景。把参数量当作排序依据会在这几组里直接得出错误结论。</p><p>重排模型在 RAG 流水线中的位置决定了它的长度需求远低于 Embedding。重排的输入是原始 query 加上粗召回得到的候选文本块，候选块通常已经在切块阶段被控制在数百 token。因此交叉编码器在 512 长度下也能工作，这也是 <code>bge-reranker-large</code>（514 长度）仍然可用的原因。真正决定重排成本的是候选数：把候选从 100 条降到 50 条，交叉编码器的推理量直接减半。工程上的常规做法是向量召回取较大候选集，重排后只保留前 5 至 10 条交给生成模型，中间环节的取舍比换模型更影响总延迟。</p><p>这里还有一处容易踩的坑：重排分数只在一个请求内可比。阿里云百炼的文档已经明确说明了这一点，开源自建同样如此——交叉编码器输出的 logits 经归一化后的绝对值受候选集构成影响。如果实现里把重排分数写入数据库当作相关性标签复用，后续查询会出现难以解释的波动。正确做法是只用分数在本次请求内排序，把阈值判断改成「取前 N 条」或「取分数高于本次最高分一定比例的条目」。</p><h4 id="_7-2-2-云厂商-api" tabindex="-1">7.2.2 云厂商 API <a class="header-anchor" href="#_7-2-2-云厂商-api" aria-label="Permalink to &quot;7.2.2 云厂商 API&quot;">​</a></h4><table tabindex="0"><thead><tr><th>服务商</th><th>模型</th><th>最大文档数</th><th>单条最大输入</th><th>单次请求最大输入</th><th>语言</th><th>备注</th><th>源</th></tr></thead><tbody><tr><td>阿里云百炼</td><td>qwen3.7-text-rerank</td><td>500</td><td>30,000 token</td><td>120,000（建议）</td><td>201 种主流语种与方言</td><td>支持 OpenAI 兼容接口</td><td>45</td></tr><tr><td>阿里云百炼</td><td>qwen3-rerank</td><td>500</td><td>4,000 token</td><td>未核实</td><td>100+ 主流语种</td><td>支持 OpenAI 兼容接口</td><td>45</td></tr><tr><td>阿里云百炼</td><td>qwen3-vl-rerank</td><td>文本 100 / 图片 40 / 视频 4</td><td>8,000 token</td><td>120,000</td><td>中、英、日、韩、法、德等 33 种</td><td>多模态，支持图片与视频</td><td>45</td></tr><tr><td>阿里云百炼</td><td>gte-rerank-v2</td><td>30</td><td>30,000 token</td><td>未核实</td><td>50 余语种</td><td>官方公告 2026-05-30 下线，推荐换用 qwen3-rerank</td><td>45</td></tr><tr><td>智谱 BigModel</td><td>rerank（<code>model</code> 枚举值即 <code>rerank</code>）</td><td>128</td><td>单条 4096 字符（query 亦为 4096 字符）</td><td>未核实</td><td>中英文</td><td>参数含 <code>top_n</code>、<code>return_documents</code>、<code>return_raw_scores</code></td><td>46</td></tr><tr><td>火山引擎方舟</td><td>rerank 模型</td><td>未核实</td><td>未核实</td><td>未核实</td><td>未核实</td><td>页面为脚本渲染，正文未取得，<strong>未核实</strong></td><td>47</td></tr></tbody></table><p>来源：45. <a href="https://help.aliyun.com/zh/model-studio/text-rerank-api" target="_blank" rel="noreferrer">阿里云百炼文本重排 API</a>；46. <a href="https://docs.bigmodel.cn/api-reference/%E6%A8%A1%E5%9E%8B-api/%E6%96%87%E6%9C%AC%E9%87%8D%E6%8E%92%E5%BA%8F" target="_blank" rel="noreferrer">智谱文本重排序 API</a>；47. <a href="https://www.volcengine.com/docs/82379/1330310" target="_blank" rel="noreferrer">火山引擎 rerank 文档</a>。</p><p><strong>阿里云百炼补充事实（一手文档）</strong></p><p><code>relevance_score</code> 取值范围 0.0–1.0，是<strong>当前请求内的相对分数</strong>，官方明确说明不可作为跨请求比较的绝对值。这一点对工程实现影响很大：不要把 rerank 分数直接落库当作「相关性阈值」使用，跨批次比较会失效。单条 Query 或 Document 超过单条限制时返回 HTTP 400，<strong>不截断输入</strong>，因此必须在调用侧自行切片。重排接口支持 <code>top_n</code>、<code>return_documents</code>、<code>instruct</code> 参数；<code>instruct</code> 仅对 <code>qwen3.7-text-rerank</code>、<code>qwen3-rerank</code>、<code>qwen3-vl-rerank</code> 生效。<code>gte-rerank-v2</code> 与 <code>qwen3-vl-rerank</code> <strong>不支持</strong> OpenAI 兼容接口，调用会返回 <code>model_not_supported</code>，接入时不要假设所有重排模型都能走同一套兼容客户端。</p><p><strong>智谱 BigModel 补充事实（一手文档）</strong></p><p>接口为 <code>POST /paas/v4/rerank</code>；<code>model</code> 为枚举值，当前可选值仅 <code>rerank</code>，默认 <code>rerank</code>。<code>query</code> 最大长度 4096 字符；<code>documents</code> 最多 128 条，单条最大长度 4096 字符。可选参数包括 <code>top_n</code>（默认 0，返回全部）、<code>return_documents</code>（默认 false）、<code>return_raw_scores</code>（默认 false）、<code>request_id</code>、<code>user_id</code>。该 API 文档页<strong>未列出具体模型版本号与价格</strong>，均未核实。</p><h3 id="_7-3-生成-llm" tabindex="-1">7.3 生成 LLM <a class="header-anchor" href="#_7-3-生成-llm" aria-label="Permalink to &quot;7.3 生成 LLM&quot;">​</a></h3><h4 id="_7-3-1-私有化侧-权重与规格" tabindex="-1">7.3.1 私有化侧：权重与规格 <a class="header-anchor" href="#_7-3-1-私有化侧-权重与规格" aria-label="Permalink to &quot;7.3.1 私有化侧：权重与规格&quot;">​</a></h4><p>参数量取 HuggingFace API 的 <code>safetensors.total</code>（张量元素总数），MoE 模型另附模型卡声明的激活参数量。上下文长度优先取模型卡声明，括号内附 <code>config.json</code> 的实际 <code>max_position_embeddings</code>。</p><table tabindex="0"><thead><tr><th>模型</th><th>发布方</th><th>参数量</th><th>激活参数</th><th>上下文</th><th>许可</th><th>私有化</th><th>源</th></tr></thead><tbody><tr><td>DeepSeek-V4-Pro</td><td>深度求索</td><td>1.6T（模型卡）</td><td>49B</td><td>1M（config 1,048,576）</td><td>MIT</td><td>是</td><td>48</td></tr><tr><td>DeepSeek-V4-Flash</td><td>深度求索</td><td>284B（模型卡）</td><td>13B</td><td>1M（config 1,048,576）</td><td>MIT</td><td>是</td><td>49</td></tr><tr><td>DeepSeek-V4.1-Flash</td><td>深度求索</td><td>552B backbone（模型卡）；safetensors 合计 763,205,315,794</td><td>未核实</td><td>1M（config 1,048,576）</td><td>MIT</td><td>是</td><td>50</td></tr><tr><td>DeepSeek-V3.2</td><td>深度求索</td><td>685,355,329,792</td><td>未核实</td><td>163,840（config）</td><td>MIT</td><td>是</td><td>51</td></tr><tr><td>DeepSeek-R1</td><td>深度求索</td><td>684,489,845,504</td><td>未核实</td><td>163,840（config）</td><td>MIT</td><td>是</td><td>52</td></tr><tr><td>Qwen3.5-397B-A17B</td><td>阿里</td><td>403,397,928,944</td><td>A17B（命名）</td><td>262,144 原生，可扩至 1,010,000</td><td>apache-2.0</td><td>是</td><td>53</td></tr><tr><td>Qwen3.5-35B-A3B</td><td>阿里</td><td>35,951,822,704</td><td>A3B（命名）</td><td>262,144 原生，可扩至 1,010,000</td><td>apache-2.0</td><td>是</td><td>54</td></tr><tr><td>Qwen3.5-9B</td><td>阿里</td><td>9,653,104,368</td><td>稠密</td><td>262,144 原生，可扩至 1,010,000</td><td>apache-2.0</td><td>是</td><td>55</td></tr><tr><td>Qwen3-235B-A22B</td><td>阿里</td><td>235,093,634,560</td><td>22B</td><td>32,768 原生，YaRN 至 131,072</td><td>apache-2.0</td><td>是</td><td>56</td></tr><tr><td>GLM-5.3</td><td>智谱</td><td>753,329,940,480</td><td>未核实</td><td>1M（config 1,048,576）</td><td>other（条款未核实）</td><td>是</td><td>57</td></tr><tr><td>GLM-5.2</td><td>智谱</td><td>753,329,940,480</td><td>未核实</td><td>1M（config 1,048,576）</td><td>MIT</td><td>是</td><td>58</td></tr><tr><td>GLM-5.1</td><td>智谱</td><td>753,864,139,008</td><td>未核实</td><td>202,752（config）</td><td>MIT</td><td>是</td><td>59</td></tr><tr><td>GLM-4.6</td><td>智谱</td><td>356,785,898,816</td><td>未核实</td><td>200K（模型卡；config 202,752）</td><td>MIT</td><td>是</td><td>60</td></tr><tr><td>Kimi-K3</td><td>月之暗面</td><td>2.8T（模型卡）；safetensors 合计 2,779,931,837,184</td><td>未核实</td><td>1M（config 1,048,576）</td><td>other（条款未核实）</td><td>是</td><td>61</td></tr><tr><td>Kimi-K2.5</td><td>月之暗面</td><td>1T（模型卡）</td><td>32B</td><td>256K（config 262,144）</td><td>other（条款未核实）</td><td>是</td><td>62</td></tr><tr><td>Kimi-K2-Thinking</td><td>月之暗面</td><td>1T（模型卡）</td><td>32B</td><td>256K（config 262,144）</td><td>other（条款未核实）</td><td>是</td><td>63</td></tr><tr><td>MiniMax-M3</td><td>MiniMax</td><td>~428B（模型卡）</td><td>~23B</td><td>1M（config 1,048,576）</td><td>other（条款未核实）</td><td>是</td><td>64</td></tr><tr><td>MiniMax-M2.5</td><td>MiniMax</td><td>228,689,764,864</td><td>未核实</td><td>196,608（config）</td><td>other（条款未核实）</td><td>是</td><td>65</td></tr><tr><td>Step-5-Preview</td><td>阶跃星辰</td><td>600B（模型卡）；safetensors 合计 604,339,504,832</td><td>27B</td><td>1M（模型卡；config 1,048,576）</td><td>StepFun Model License 1.0（<code>other</code>）</td><td>是</td><td>66</td></tr><tr><td>Step-3.5-Flash</td><td>阶跃星辰</td><td>196.81B（模型卡）；safetensors 合计 199,384,301,376</td><td>~11B</td><td>256K（模型卡；config 262,144）</td><td>apache-2.0</td><td>是</td><td>67</td></tr><tr><td>Baichuan-M3-235B</td><td>百川智能</td><td>235,093,634,560</td><td>未核实</td><td>40,960（config）</td><td>apache-2.0</td><td>是</td><td>68</td></tr><tr><td>Yi-1.5-34B-Chat</td><td>零一万物</td><td>未核实⁴</td><td>未核实</td><td>4096（config）</td><td>未核实⁴</td><td>是</td><td>69</td></tr></tbody></table><p>来源：48. <a href="https://huggingface.co/deepseek-ai/DeepSeek-V4-Pro" target="_blank" rel="noreferrer">deepseek-ai/DeepSeek-V4-Pro</a>；49. <a href="https://huggingface.co/deepseek-ai/DeepSeek-V4-Flash" target="_blank" rel="noreferrer">deepseek-ai/DeepSeek-V4-Flash</a>；50. <a href="https://huggingface.co/deepseek-ai/DeepSeek-V4.1-Flash" target="_blank" rel="noreferrer">deepseek-ai/DeepSeek-V4.1-Flash</a>；51. <a href="https://huggingface.co/deepseek-ai/DeepSeek-V3.2" target="_blank" rel="noreferrer">deepseek-ai/DeepSeek-V3.2</a>；52. <a href="https://huggingface.co/deepseek-ai/DeepSeek-R1" target="_blank" rel="noreferrer">deepseek-ai/DeepSeek-R1</a>；53. <a href="https://huggingface.co/Qwen/Qwen3.5-397B-A17B" target="_blank" rel="noreferrer">Qwen/Qwen3.5-397B-A17B</a>；54. <a href="https://huggingface.co/Qwen/Qwen3.5-35B-A3B" target="_blank" rel="noreferrer">Qwen/Qwen3.5-35B-A3B</a>；55. <a href="https://huggingface.co/Qwen/Qwen3.5-9B" target="_blank" rel="noreferrer">Qwen/Qwen3.5-9B</a>；56. <a href="https://huggingface.co/Qwen/Qwen3-235B-A22B" target="_blank" rel="noreferrer">Qwen/Qwen3-235B-A22B</a>；57. <a href="https://huggingface.co/zai-org/GLM-5.3" target="_blank" rel="noreferrer">zai-org/GLM-5.3</a>；58. <a href="https://huggingface.co/zai-org/GLM-5.2" target="_blank" rel="noreferrer">zai-org/GLM-5.2</a>；59. <a href="https://huggingface.co/zai-org/GLM-5.1" target="_blank" rel="noreferrer">zai-org/GLM-5.1</a>；60. <a href="https://huggingface.co/zai-org/GLM-4.6" target="_blank" rel="noreferrer">zai-org/GLM-4.6</a>；61. <a href="https://huggingface.co/moonshotai/Kimi-K3" target="_blank" rel="noreferrer">moonshotai/Kimi-K3</a>；62. <a href="https://huggingface.co/moonshotai/Kimi-K2.5" target="_blank" rel="noreferrer">moonshotai/Kimi-K2.5</a>；63. <a href="https://huggingface.co/moonshotai/Kimi-K2-Thinking" target="_blank" rel="noreferrer">moonshotai/Kimi-K2-Thinking</a>；64. <a href="https://huggingface.co/MiniMaxAI/MiniMax-M3" target="_blank" rel="noreferrer">MiniMaxAI/MiniMax-M3</a>；65. <a href="https://huggingface.co/MiniMaxAI/MiniMax-M2.5" target="_blank" rel="noreferrer">MiniMaxAI/MiniMax-M2.5</a>；66. <a href="https://huggingface.co/stepfun-ai/Step-5-Preview" target="_blank" rel="noreferrer">stepfun-ai/Step-5-Preview</a>；67. <a href="https://huggingface.co/stepfun-ai/Step-3.5-Flash" target="_blank" rel="noreferrer">stepfun-ai/Step-3.5-Flash</a>；68. <a href="https://huggingface.co/baichuan-inc/Baichuan-M3-235B" target="_blank" rel="noreferrer">baichuan-inc/Baichuan-M3-235B</a>；69. <a href="https://huggingface.co/01-ai/Yi-1.5-34B-Chat" target="_blank" rel="noreferrer">01-ai/Yi-1.5-34B-Chat</a>。</p><p>注释：</p><ol start="4"><li><code>01-ai/Yi-1.5-34B-Chat</code> 的 HuggingFace API 抓取失败（连接中断），仅取得 <code>config.json</code>（<code>model_type=llama</code>、<code>hidden_size=7168</code>、<code>num_hidden_layers=60</code>、<code>max_position_embeddings=4096</code>）；参数量与许可<strong>未核实</strong>。该模型发布于 2024 年，已非当前主力选项，列出仅为覆盖存量的历史选型。</li></ol><p>几点口径说明。命名中的 A17B、A3B 是官方命名，未在模型卡表格中逐项核实，因此「激活参数」列对 <code>Qwen3.5-397B-A17B</code>、<code>Qwen3.5-35B-A3B</code> 保留命名原文而未转写为数字。<code>DeepSeek-V4-Pro</code>、<code>DeepSeek-V4-Flash</code>、<code>Kimi-K2.5</code>、<code>Kimi-K2-Thinking</code> 的参数量同样来自模型卡声明而非 <code>safetensors</code> 汇总，与同表中带完整数字的行不是同一证据等级。<code>DeepSeek-V4.1-Flash</code> 的模型卡声明为 552B backbone，而 <code>safetensors</code> 合计为 763,205,315,794，两个口径差异明显，选型估算显存时应以实际权重文件大小为准。<code>MiniMax-M3</code> 的 ~428B 与 ~23B 带约等号，是模型卡的估算表述，不是精确值。</p><p>这张表最需要留意的是「激活参数」这一列的含义。总参数量决定权重文件的体积与加载显存，激活参数量决定单次前向推理的算力开销。MoE 架构的模型正是靠这两者的差值来同时获得较大的知识容量与较低的推理成本，因此只看总参数量会把 MoE 模型的部署成本估高。但上表中 <code>DeepSeek-V4-Pro</code>（49B）、<code>DeepSeek-V4-Flash</code>（13B）、<code>Qwen3-235B-A22B</code>（22B）、<code>Kimi-K2.5</code>（32B）、<code>MiniMax-M3</code>（~23B）、<code>Step-5-Preview</code>（27B）、<code>Step-3.5-Flash</code>（~11B）的激活参数量有明确数值，而 <code>DeepSeek-V4.1-Flash</code>、<code>GLM-5.3</code>、<code>GLM-5.2</code>、<code>GLM-5.1</code>、<code>GLM-4.6</code>、<code>Kimi-K3</code>、<code>MiniMax-M2.5</code>、<code>Baichuan-M3-235B</code>、<code>Yi-1.5-34B-Chat</code> 等行的激活参数量为未核实，评估这些模型时不能凭总参数量反推算力需求。</p><p><code>Qwen3.5-9B</code> 在这张表中是一个特殊位置。它的参数量为 9,653,104,368，是「稠密」模型，262,144 原生上下文可扩展至 1,010,000，许可为 apache-2.0。表中的 MoE 大模型虽然有更低的激活参数量比，但权重文件仍然巨大，而稠密 9B 在单机单卡场景下更容易落地，同时上下文窗口与同系列的大模型一致。对预算有限又要私有化的团队，这是需要重点评测的一档。</p><p>上下文的标注方式也有两处需要小心。<code>GLM-4.6</code> 与 <code>Step-3.5-Flash</code> 的上下文是「模型卡声明值；config 实测值」并列，两者相差很小（200K 对 202,752；256K 对 262,144），可以按模型卡值理解。但 <code>Qwen3.5</code> 系列的「262,144 原生，可扩展至 1,010,000」需要区分：原生值来自模型配置，扩展值依赖 YaRN 之类的长度外推手段，外推后的注意力质量需要自行验证，不能按原生窗口的效果预期使用。<code>Qwen3-235B-A22B</code> 的「32,768 原生，YaRN 至 131,072」属于同一情况，且其原生窗口只有 32,768，在上表中属于偏小的一档，做整本文档问答时长度会成为限制。</p><h4 id="_7-3-2-api-侧-能力与价格" tabindex="-1">7.3.2 API 侧：能力与价格 <a class="header-anchor" href="#_7-3-2-api-侧-能力与价格" aria-label="Permalink to &quot;7.3.2 API 侧：能力与价格&quot;">​</a></h4><table tabindex="0"><thead><tr><th>模型 / 服务</th><th>长上下文</th><th>函数调用 / 结构化输出</th><th>官方配套 Embedding / Rerank</th></tr></thead><tbody><tr><td>deepseek-flash（DeepSeek-V4.1-Flash-1017）</td><td>1M，输出最大 384K</td><td>官方文档明确：Json Output 支持、Tool Calls 支持；另有 Responses API、Anthropic API</td><td>未见官方 Embedding / Rerank 模型</td></tr><tr><td>deepseek-v4-pro（DeepSeek-V4-Pro-0813）</td><td>1M，输出最大 384K</td><td>同上</td><td>未见官方 Embedding / Rerank 模型</td></tr><tr><td>Qwen3.5 系列</td><td>262,144 原生，可扩展至 1,010,000</td><td>模型卡与百炼文档均列出工具调用相关能力</td><td>有：Qwen3-Embedding / Qwen3-Reranker / Qwen3-VL 系列</td></tr><tr><td>GLM-5.3</td><td>1M</td><td>官方文档目录含「工具调用 / 结构化输出 / 上下文缓存」章节（能力项未逐条核实）</td><td>有：embedding-3；rerank 模型存在但参数未核实</td></tr><tr><td>Kimi-K3 / K2.5</td><td>1M / 256K</td><td>模型卡描述为 agentic 模型，支持工具调用（具体能力项未逐条核实）</td><td>未见官方 Embedding / Rerank 模型</td></tr><tr><td>MiniMax-M3</td><td>1M，多模态</td><td>未逐条核实</td><td>未见官方 Embedding / Rerank 模型</td></tr><tr><td>Step-3.5-Flash</td><td>256K</td><td>未逐条核实</td><td>未见官方 Embedding / Rerank 模型</td></tr></tbody></table><p>配套关系是 RAG 选型中容易被忽略的一列。生成模型自带 Embedding 与 Reranker，意味着 query 改写、指令前缀、打分接口的风格可以对齐，联调成本更低；反之，若生成侧用 DeepSeek 而检索侧用 Qwen，需要自行承担两侧 prompt 约定不一致带来的调参工作。</p><p><strong>API 价格量级</strong>（官方定价页展示价，以控制台结算为准）</p><table tabindex="0"><thead><tr><th>服务商</th><th>模型</th><th>输入（缓存命中）</th><th>输入（缓存未命中）</th><th>输出</th><th>上下文</th><th>源</th></tr></thead><tbody><tr><td>DeepSeek</td><td>deepseek-flash</td><td>空闲 0.02 元 / 高峰 0.04 元（每百万 token）</td><td>空闲 1 元 / 高峰 2 元</td><td>空闲 4 元 / 高峰 8 元</td><td>1M</td><td>70</td></tr><tr><td>DeepSeek</td><td>deepseek-v4-pro</td><td>空闲 0.15 元 / 高峰 0.30 元</td><td>空闲 4.5 元 / 高峰 9.0 元</td><td>空闲 13.5 元 / 高峰 27.0 元</td><td>1M</td><td>70</td></tr><tr><td>阿里云百炼</td><td>未见 embedding 之外的 LLM 单价表¹</td><td>未核实</td><td>未核实</td><td>未核实</td><td>—</td><td>71</td></tr></tbody></table><p>来源：70. <a href="https://api-docs.deepseek.com/zh-cn/quick_start/pricing" target="_blank" rel="noreferrer">DeepSeek 定价页</a>；71. <a href="https://help.aliyun.com/zh/model-studio/models" target="_blank" rel="noreferrer">阿里云百炼模型大全</a>。</p><p>注：</p><ol><li>阿里云百炼模型大全页确认在架以下文本生成模型：<code>qwen4-max</code>、<code>qwen3.7-plus</code>、<code>qwen3.8-flash</code>、<code>deepseek-v4-pro-0813</code>、<code>deepseek-v4.1-flash</code>、<code>kimi/kimi-k3</code>、<code>kimi-k3</code>、<code>glm-5.3</code>、<code>ZHIPU/GLM-5.3</code>、<code>MiniMax-M3.1-Flash</code>、<code>mimo-v2.6-pro-ultraspeed</code>。<strong>具体单价未在本次抓取中取得，未核实。</strong></li></ol><p>DeepSeek 官方并发限制（一手文档）：<code>deepseek-flash</code> 为 2500，<code>deepseek-v4-pro</code> 为 500。高峰时段为北京时间周一至周五（不含法定节假日）9:00–12:00 与 14:00–18:00，其余时段为空闲时段，空闲价为高峰价的一半。官方另说明：自 2026-11-18 12:00 起，服务端搜索与网页抓取的工具调用本身不再单独计费。</p><p>DeepSeek 官方版本时间线可用于核对新旧（来源：<a href="https://api-docs.deepseek.com/zh-cn/news/news260813/" target="_blank" rel="noreferrer">DeepSeek API Docs 新闻</a>）：DeepSeek-V4-Pro 正式版 2026-08-13；DeepSeek-V4 预览版 2026-04-24；DeepSeek-V4.1-Flash 2026-09-10；DeepSeek-V4.1-Flash-1017 2026-10-17；DeepSeek-V3.2 正式版 2025-12-01；DeepSeek-V3.2-Exp 2025-09-29；DeepSeek-V3.1 2025-08-21；DeepSeek-R1 2025-01-20。</p><h3 id="_7-4-选型建议" tabindex="-1">7.4 选型建议 <a class="header-anchor" href="#_7-4-选型建议" aria-label="Permalink to &quot;7.4 选型建议&quot;">​</a></h3><p>以下建议均为基于本章素材的推断，不是实测结论。凡涉及「效果更好」的判断，都需在自有语料上评测后再定。</p><p><strong>纯中文、成本敏感、单机私有化。</strong> <code>BAAI/bge-m3</code> 是最稳的默认：1024 维、8192 长度、MIT 许可，长度足以容纳整段产品说明或法务条款。若机器只有 CPU 或小显存，退到 <code>bge-small-zh-v1.5</code>（512 维）或 <code>bge-base-zh-v1.5</code>。生成侧取 <code>Qwen3.5-9B</code>（稠密，9,653,104,368 参数，262,144 原生上下文，apache-2.0），是这张表里私有化门槛最低的一档。</p><p><strong>多语言、跨语种检索。</strong> 用 <code>Qwen/Qwen3-Embedding-0.6B/4B/8B</code>，按显存三选一，均 apache-2.0。注意可变维度是按 MRL 截断，例如把 4096 维降到 1024 维会损失精度，需自行评测，不要默认截断后等价。</p><p><strong>长文档、需要可变维度省存储。</strong> <code>Qwen3-Embedding-4B</code>（2560 维）或 <code>Qwen3-Embedding-0.6B</code>（1024 维）降本；也可考虑 <code>Conan-embedding-v2</code>（3584 维、32K 上下文、apache-2.0），但其仓库无 <code>config.json</code>，工程接入需自行适配，属于有额外集成成本的选择。</p><p><strong>多模态（检索图片或视频）。</strong> 开源选 <code>Qwen3-VL-Embedding-8B</code> 搭配 <code>Qwen3-VL-Reranker-8B</code>（均 apache-2.0，30+ 语言）；API 侧可选火山方舟 <code>doubao-embedding-vision</code> 系列（默认 2048 维，支持稀疏与多向量），或阿里云 <code>qwen3-vl-rerank</code>（33 种语言）。注意方舟侧单价与最大输入长度均未核实，做预算前必须先询价。</p><p><strong>效果优先、能上 GPU。</strong> <code>Qwen/Qwen3-Embedding-8B</code>（4096 维）与 <code>Qwen/Qwen3-Reranker-4B</code> 组合，两者均 apache-2.0，商用路径清晰。重排若只做中文，可在 <code>bge-reranker-large</code>（560M）与 <code>bge-reranker-v2-m3</code> 之间实测比较；多语言场景直接选 <code>bge-reranker-v2-m3</code>（567M，apache-2.0），是性价比与显存占用的折中点。</p><p><strong>成本敏感、走 API。</strong> Embedding 用阿里云百炼 <code>qwen3.7-text-embedding-flash</code>（0.000125 元/千 token）或 <code>text-embedding-v4</code>（0.0005 元/千 token）；生成用 DeepSeek <code>deepseek-flash</code>，空闲时段缓存未命中的输入价为 1 元/百万 token，是本章素材中的价格低位。若调用时段集中在工作日 9:00–12:00 与 14:00–18:00，实际按高峰价计，成本约为空闲价的两倍，容量规划时要按高峰价做预算。</p><p><strong>长上下文 RAG（整本文档、长订单历史）。</strong> 生成侧可选 <code>DeepSeek-V4.1-Flash</code>（1M）、<code>Kimi-K3</code>（1M）、<code>MiniMax-M3</code>（1M）、<code>Step-5-Preview</code>（1M）、<code>Qwen3.5</code> 系列（262K 原生，可扩展 1M）。但需注意：超长上下文会显著抬高推理成本，优先用「检索 + 中等上下文」而不是直接把 1M 塞满。在多数企业文档问答场景中，先把检索质量做扎实比放宽上下文窗口更划算。</p><p>关于 MTEB 与 C-MTEB 榜单：素材未取得可引用的排名数值（页面为脚本动态渲染），因此本章不引用任何榜单分数。若选型需要榜单支撑，请自行重新抓取并复核原文。</p><p>榜单与直觉都不能替代自有语料评测，这也是本章所有建议都标注为推断的原因。一个可执行的最小评测流程是：从实际业务语料中抽取若干条 query，为每条标注正确的文档块，固定切块策略与候选数后，只替换 Embedding 模型或 Reranker 模型，比较召回率与首位命中率。这样得到的是相对排序，与官方文档提示的「不同配置下的绝对分数不可直接比较」的口径一致。评测时至少要覆盖两类查询：一类是关键词明确的查询，一类是需要语义匹配的查询。前者容易在小模型上得到好成绩，后者才能体现大模型与长上下文的价值。若两类查询的表现差距很大，说明问题出在切块或重排环节，而不是 Embedding 模型本身，此时换更大的模型并不能解决。</p><p>另外建议在评测阶段就固定向量库的维度上限。可变维度模型虽然灵活，但一旦上线后再改维度，需要全量重新编码与重建索引，成本远高于在评测阶段多跑几组对比。以本表的 <code>Qwen3-Embedding-8B</code> 为例，4096 维与截断到 1024 维是两个不同的索引方案，应在评测时同时测出质量差异，再决定是否用质量换存储。</p><h3 id="_7-5-许可与合规风险提示" tabindex="-1">7.5 许可与合规风险提示 <a class="header-anchor" href="#_7-5-许可与合规风险提示" aria-label="Permalink to &quot;7.5 许可与合规风险提示&quot;">​</a></h3><p>这一节的内容优先级高于效果对比。许可判断错误会导致产品无法商用，属于不可用返工，选型阶段必须逐条落定，不能默认「开源即可商用」。</p><p><strong>明确禁止商用。</strong> <code>TencentBAC/Conan-embedding-v1</code> 的 HF 许可为 <strong>CC-BY-NC-4.0</strong>，即禁止商用。该模型规格（325,522,432 参数、1024 维、512 长度、中文）在中文短文本检索场景中有吸引力，但任何面向商业交付的系统都不得将其纳入。若需要同族能力，改用 <code>Conan-embedding-v2</code>（apache-2.0，3584 维、32K 上下文），代价是需要自行适配无 <code>config.json</code> 的仓库结构。</p><p><strong>许可标签为 <code>other</code>，商用前须逐条核对官方许可文本。</strong> 涉及 <code>GLM-5.3</code>、<code>Kimi-K3</code>、<code>MiniMax-M3</code>、<code>Step-5-Preview</code> 等模型，另有 <code>Kimi-K2.5</code>、<code>Kimi-K2-Thinking</code>、<code>MiniMax-M2.5</code>。<code>other</code> 只表示 HuggingFace 未映射到标准许可标识，不等于无限制开源，也不等于禁止商用——它表示<strong>必须读原文才能判断</strong>。其中 <code>Step-5-Preview</code> 的模型卡已给出具体名称：StepFun Model License 1.0（标签仍为 <code>other</code>），应直接以该许可全文为准。本章未取得任何一个 <code>other</code> 标签对应的条款内容，因此不对其商用可行性做任何判断。</p><p><strong>非标准开源许可。</strong> <code>bge-multilingual-gemma2</code> 与 <code>bge-reranker-v2.5-gemma2-lightweight</code> 为 Gemma 许可，不是标准开源许可。Gemma 许可通常包含使用限制与分发义务，与 MIT、apache-2.0 不可等同处理，纳入前应单独走一遍法务确认。</p><p><strong>同族替换是较清晰的合规路径。</strong> 在需求允许的前提下，优先选择同族的宽松许可版本：<code>GLM-5.2</code>、<code>GLM-4.6</code> 为 MIT，<code>Step-3.5-Flash</code> 为 apache-2.0。它们与 <code>other</code> 标签的同族模型能力定位接近，但许可边界明确，能显著降低合规评审成本。</p><p><strong>存量下线的服务。</strong> 阿里云百炼 <code>gte-rerank-v2</code> 的官方公告下线日期为 <strong>2026-05-30</strong>，应改用 <code>qwen3-rerank</code>。需要注意两点：其一，本章来源标注的抓取与查看日期为 2026-11-24，该日期已晚于下线日期，若仍在使用该服务，应立即核实账号下的实际可用状态，不要依赖本文档的结论；其二，素材中该条目的原始表述为「将于 2026-05-30 下线」，属公告时点的未来时态，与本文档的查看日期存在时态差异，按本文档口径应表述为「已于 2026-05-30 下线」。此外，<code>gte-rerank-v2</code> 与 <code>qwen3-vl-rerank</code> 都不支持 OpenAI 兼容接口，迁移时不能只改模型名，调用客户端也要一并调整。</p><p><strong>其他需要在合规评审中一并确认的点。</strong> <code>core-emb-*</code>、<code>core-reranker-*</code>、<code>UEmbed-9B</code> 为 CC-BY-4.0，属于非标准开源许可，通常带署名要求，需确认分发场景下的署名方式。<code>moka-ai/m3e-large</code> 未标注许可，<code>moka-ai/m3e-base</code> 的许可与参数量均未核实，<code>shibing624/text2vec-large-chinese</code> 仓库返回 HTTP 401、全部字段未核实——这三者的许可状态都属于<strong>无法确认</strong>，不应在有合规要求的项目中使用。火山引擎方舟 <code>doubao-embedding-vision-250615</code> 已停止新购、存量可用，新项目不应再以它作为方案基线。最后，来源中标注为 <code>license:other</code> 的模型，其具体条款内容在本次抓取中<strong>均未取得</strong>，任何商用决策都必须以官方许可全文为准，不能以本章表格作为依据。</p><p>把上述风险收成一张决策清单，选型评审时按顺序过一遍即可。第一步，看许可标识：MIT 与 apache-2.0 可以直接推进；CC-BY-NC 直接排除；CC-BY-4.0 确认署名义务；Gemma 许可与 <code>other</code> 标签一律停下，读原文后再判定。第二步，看证据完整性：规格中只要有关键字段是「未核实」，就要判断该字段是否影响部署决策。参数量未核实不影响功能，但影响显存预算；许可未核实则直接阻断商用。第三步，看服务在架状态：云服务要确认是否已公告下线、是否已停止新购。第四步，看同族是否有宽松许可的替代版本，有则优先替换，用能力上的小幅让步换取合规路径的确定性。</p><p>需要强调本章的能力边界：这里只对许可状态做归类与提示，不做法律判断。CC-BY-NC-4.0 禁止商用这一条结论直接来自许可标识本身，属于可确认的事实；而 <code>other</code> 标签下各模型究竟允许什么，本章既未取得条款文本，也不具备解释条款的依据，必须由法务或厂商官方答复来定。把「未核实」当作「默认可商用」是最危险的误读，本章特意保留这些空白单元格，正是为了避免这种误读。</p>',93)])])}const p=t(a,[["render",n]]);export{b as __pageData,p as default};
